        return [row[:] for row in grid]
    by_residue = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                residue = (c - r) % period
                by_residue[residue] = value
    # Repeating diagonals are determined by c-r modulo the number of bands.
    # In case a residue was not directly represented, use the nearest known
    # residue cyclically (ordinary instances represent every residue).
    known = sorted(by_residue)
    if not known:
        return [row[:] for row in grid]
    def color_at(residue):
        if residue in by_residue:
            return by_residue[residue]
        return by_residue[min(known, key=lambda k: (residue-k) % period)]
    h, w = len(grid), len(grid[0])
    return [[color_at((c-r) % period) for c in range(w)] for r in range(h)]
