 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each observed nonzero diagonal is one position in the repeating pattern.
    diagonal_colors = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                d = c - r
                if d in diagonal_colors and diagonal_colors[d] != value:
                    raise ValueError("inconsistent colors on a diagonal")
                diagonal_colors[d] = value
    period = len(diagonal_colors)
    if period == 0:
        return [row[:] for row in grid]
    pattern = {d % period: color for d, color in diagonal_colors.items()}
    if len(pattern) != period:
        raise ValueError("diagonal observations do not define a full period")
    return [[pattern[(c-r) % period] for c in range(w)] for r in range(h)]
